const stageNo=Number(document.body.dataset.stage||1);
const STAGES={1:{name:'STAGE 1：コイン収集',start:70,end:1580,threshold:350,next:'stage2.html',goal:'ステージ1クリア！'},2:{name:'STAGE 2：高難度エリア',start:1580,end:3150,threshold:750,next:'boss.html',goal:'ボス挑戦権を獲得！'},3:{name:'BOSS：象の老武術家',start:3150,end:4180,threshold:0,next:'',goal:'ボス撃破！'}};
const stage=STAGES[stageNo]||STAGES[1];
function readCarry(){try{return Number(localStorage.getItem('shakureLionCarryScore')||0)||0;}catch(e){return 0;}}
function saveCarry(v){try{localStorage.setItem('shakureLionCarryScore',String(v));}catch(e){}}

const SHEET='assets/character_sheet.png';
const sheet=new Image();sheet.src=SHEET;
const SPRITE_DATA={"idle":"","run1":"","run2":"","jump":"","crouch":""};
const sprites={};
for(const [name,data] of Object.entries(SPRITE_DATA)){const im=new Image();im.src=data;sprites[name]=im;}
const BOSS_FRAME='assets/boss.webp';
const BOSS_FRAMES=[BOSS_FRAME,BOSS_FRAME,BOSS_FRAME,BOSS_FRAME];
const bossSprites=stageNo===3?BOSS_FRAMES.map(data=>{const im=new Image();im.src=data;return im;}):[];
const c=document.getElementById('game'),ctx=c.getContext('2d'),W=960,H=540;
const keys={left:false,right:false,jump:false,down:false};let active=false,frame=0,camera=0,coins=0,lives=3,powered=false,chinLevel=0,timeLeft=90,lastTick=0,resultShown=false;
const worldW=4300,hero={x:stage.start,y:320,w:58,h:82,vx:0,vy:0,ground:false,face:1,inv:0,wantJump:false};
const platforms=[{x:0,y:462,w:620,h:100},{x:700,y:462,w:460,h:100},{x:1240,y:462,w:480,h:100},{x:1800,y:462,w:480,h:100},{x:2360,y:462,w:480,h:100},{x:2920,y:462,w:1380,h:100},{x:270,y:370,w:130,h:20},{x:465,y:310,w:110,h:20},{x:790,y:370,w:140,h:20},{x:1010,y:310,w:100,h:20},{x:1330,y:370,w:120,h:20},{x:1510,y:305,w:120,h:20},{x:1900,y:365,w:140,h:20},{x:2110,y:300,w:110,h:20},{x:2450,y:370,w:130,h:20},{x:2650,y:310,w:120,h:20},{x:3050,y:370,w:130,h:20},{x:3270,y:300,w:150,h:20}];
let coinList=[],mushrooms=[],enemies=[];
const boss={x:3650,y:332,w:150,h:130,hp:5,maxHp:5,alive:true,mode:"wait",modeTimer:0,attackCooldown:0,hitCooldown:0,flash:0,chargeDir:1};
let bossDefeated=false,bossDefeatTimeLeft=null;
function reset(){hero.x=stage.start;hero.y=320;hero.vx=hero.vy=0;hero.inv=0;hero.face=1;hero.ground=false;hero.wantJump=false;camera=Math.max(0,stage.start-W*.36);coins=0;lives=3;powered=false;chinLevel=0;timeLeft=90;lastTick=performance.now();resultShown=false;frame=0;boss.x=3650;boss.y=332;boss.hp=boss.maxHp;boss.alive=true;boss.mode="wait";boss.modeTimer=0;boss.attackCooldown=0;boss.hitCooldown=0;boss.flash=0;boss.chargeDir=1;bossDefeated=false;bossDefeatTimeLeft=null;document.getElementById("bossStat").style.display=stageNo===3?"inline-block":"none";
 coinList=[];for(let x=Math.max(190,stage.start+80);x<stage.end-70;x+=145)coinList.push({x,y:[405,330,390,270,420][Math.floor(x/145)%5],got:false});
 mushrooms=[620,1690,2810,3420].filter(x=>x>=stage.start-80&&x<stage.end).map(x=>({x,y:430,got:false,lucky:Math.random()<0.5,nextSwitch:frame+randomMushroomPeriod()}));
 enemies=[{x:520,y:430,min:480,max:590,v:1.2,alive:true},{x:900,y:430,min:810,max:1080,v:1.5,alive:true},{x:1450,y:430,min:1280,max:1540,v:1.7,alive:true},{x:2020,y:430,min:1850,max:2240,v:1.5,alive:true},{x:2520,y:430,min:2400,max:2800,v:1.8,alive:true},{x:3260,y:430,min:3200,max:3400,v:1.7,alive:true}].filter(e=>stageNo<3&&e.x>=stage.start-100&&e.x<stage.end);ui();}
function randomMushroomPeriod(){return 28+Math.floor(Math.random()*78);}
function ui(){document.getElementById('coins').textContent=coins;document.getElementById('lives').textContent=lives;document.getElementById('chin').textContent=(chinLevel>0?'+':'')+chinLevel;const t=document.getElementById('timer');if(t)t.textContent=Math.max(0,timeLeft).toFixed(1);const bh=document.getElementById("bossHp");if(bh)bh.textContent=Math.max(0,boss.hp);}
function title(){document.getElementById('overlay').style.display='flex';const intro=stageNo===1?'コインを集め、キノコでアゴを伸ばそう。ゴール時に350点以上ならSTAGE 2へ！':stageNo===2?'前ステージのスコアを引き継いで挑戦。累計750点以上でボス戦へ！':'象の老武術家との決戦！アゴレベル2以上で、突進後の隙に正面から接触して攻撃しよう。';document.getElementById('panel').innerHTML=`<h2>${stage.name}</h2><img class="preview" src="${SHEET}" alt="主人公キャラクターデザイン画"><p>${intro}</p><p>制限時間90秒。スマホは画面下の操作ボタン、PCは← → / A・D、Spaceで操作。</p><button id="start">${stageNo===3?'ボスに挑戦！':'ステージスタート！'}</button>`;document.getElementById('start').onclick=()=>{if(stageNo===1){try{localStorage.removeItem('shakureLionCarryScore')}catch(e){}}reset();active=true;document.getElementById('overlay').style.display='none';};}
function end(title,msg){if(resultShown)return;resultShown=true;active=false;const a=Math.max(0,chinLevel)*100,b=coins*10,t=Math.max(0,Math.floor(timeLeft))*5,bossBonus=bossDefeated&&bossDefeatTimeLeft!==null?Math.floor(Math.max(0,bossDefeatTimeLeft))*10:0,stageScore=a+b+t+bossBonus,carry=stageNo===1?0:readCarry(),total=carry+stageScore,grade=total>=2200?'S':total>=1500?'A':total>=850?'B':'C';document.getElementById('overlay').style.display='flex';document.getElementById('panel').innerHTML=`<h2>${title}</h2><p>${msg}</p><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin:12px 0"><div style="background:#263a59;border-radius:10px;padding:9px 3px"><b>🦷 アゴ</b><br><strong>${chinLevel}</strong><br><small>${a} pt</small></div><div style="background:#263a59;border-radius:10px;padding:9px 3px"><b>🪙 コイン</b><br><strong>${coins}枚</strong><br><small>${b} pt</small></div><div style="background:#263a59;border-radius:10px;padding:9px 3px"><b>⏱️ 残り時間</b><br><strong>${Math.max(0,timeLeft).toFixed(1)}秒</strong><br><small>${t} pt</small></div><div style="background:#493b24;border-radius:10px;padding:9px 3px"><b>👊 ボス撃破ボーナス</b><br><strong>${bossDefeatTimeLeft===null?'未獲得':Math.max(0,bossDefeatTimeLeft).toFixed(1)+'秒時点'}</strong><br><small>+${bossBonus} pt</small></div></div><p>今回：<b>${stageScore} pt</b>　引継ぎ：<b>${carry} pt</b></p><h2 style="font-size:28px">累計 ${total} pt（${grade}）</h2><button id="again">もう一度プレイ</button> <button id="home">タイトルへ</button>`;document.getElementById('again').onclick=()=>{reset();active=true;document.getElementById('overlay').style.display='none';};document.getElementById('home').onclick=()=>location.href='index.html';}
function finishGate(){if(resultShown)return;active=false;const stageScore=Math.max(0,chinLevel)*100+coins*10+Math.max(0,Math.floor(timeLeft))*5,carry=stageNo===1?0:readCarry(),total=carry+stageScore;if(stageNo===3){end('🏆 ボス撃破！','象の老武術家を撃破してゴール到着！');return;}resultShown=true;document.getElementById('overlay').style.display='flex';let passed=total>=stage.threshold;let headline=stageNo===3?'🏆 ボス撃破！':passed?stage.goal:'挑戦終了';let desc=stageNo===3?'象の老武術家を撃破してゴール到着！':passed?`今回 ${stageScore} pt、累計 ${total} pt。条件達成！次のステージへ進もう。`:`今回 ${stageScore} pt、累計 ${total} pt。必要な累計スコアは ${stage.threshold} pt。`;if(passed)saveCarry(total);document.getElementById('panel').innerHTML=`<h2>${headline}</h2><p>${desc}</p><p>アゴ：${chinLevel}　／　コイン：${coins}枚　／　残り時間：${Math.max(0,timeLeft).toFixed(1)}秒</p><p>今回のスコア：<b>${stageScore} pt</b><br>累計スコア：<b>${total} pt</b></p>${passed?`<button id="next">${stageNo===1?'STAGE 2へ進む':'ボスに挑戦！'}</button>`:'<button id="again">もう一度挑戦</button>'} <button id="home">タイトルへ</button>`;const next=document.getElementById('next');if(next)next.onclick=()=>location.href=stage.next;const again=document.getElementById('again');if(again)again.onclick=()=>{reset();active=true;document.getElementById('overlay').style.display='none';};document.getElementById('home').onclick=()=>location.href='index.html';}
function key(e,v){const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown',' ','a','d','w','s'].includes(k))e.preventDefault();if(k==='arrowleft'||k==='a')keys.left=v;if(k==='arrowright'||k==='d')keys.right=v;if(k==='arrowdown'||k==='s')keys.down=v;if(k==='arrowup'||k==='w'||k===' '){if(v&&!keys.jump)hero.wantJump=true;keys.jump=v;}}
addEventListener('keydown',e=>key(e,true));addEventListener('keyup',e=>key(e,false));addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;const dn=e=>{e.preventDefault();if(k==='jump'&&!keys.jump)hero.wantJump=true;keys[k]=true;};const up=e=>{e.preventDefault();keys[k]=false;};b.addEventListener('pointerdown',dn);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up);});
function hit(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
let toastText='',toastUntil=0;function showToast(t){toastText=t;toastUntil=frame+100;}function damage(){if(hero.inv)return;lives--;hero.inv=100;hero.vy=-7;hero.vx=hero.x<camera+W/2?-4:4;ui();if(lives<=0)end('ゲームオーバー','もう一度挑戦しよう！');}
function update(){if(!active)return;const now=performance.now();if(!lastTick)lastTick=now;timeLeft-=Math.min(0.05,Math.max(0,(now-lastTick)/1000));lastTick=now;if(timeLeft<=0){timeLeft=0;ui();end("タイムアップ！","制限時間内にゴールできなかった！");return;}frame++;hero.vx=(keys.right?4.5:0)-(keys.left?4.5:0);if(hero.vx)hero.face=hero.vx>0?1:-1;hero.x=Math.max(stage.start,Math.min(stage.end-hero.w,hero.x+hero.vx));
 const oldY=hero.y;if(hero.wantJump&&hero.ground){hero.vy=-13.4;hero.ground=false;}hero.wantJump=false;hero.vy=Math.min(15,hero.vy+.62);hero.y+=hero.vy;hero.ground=false;
 for(const p of platforms)if(hero.x+hero.w>p.x&&hero.x<p.x+p.w&&oldY+hero.h<=p.y&&hero.y+hero.h>=p.y&&hero.vy>=0){hero.y=p.y-hero.h;hero.vy=0;hero.ground=true;}
 if(hero.y>H+80){damage();hero.y=300;hero.vy=0;}
 for(const q of coinList)if(!q.got&&Math.hypot(hero.x+hero.w/2-q.x,hero.y+hero.h/2-q.y)<38){q.got=true;coins++;ui();}
 for(const m of mushrooms){if(!m.got&&frame>=m.nextSwitch){m.lucky=!m.lucky;m.nextSwitch=frame+randomMushroomPeriod();}if(!m.got&&Math.abs(hero.x+hero.w/2-m.x)<42&&Math.abs(hero.y+hero.h/2-m.y)<52){m.got=true;if(m.lucky){chinLevel=Math.min(8,chinLevel+2);coins+=3;showToast("大当たり！ アゴ +2 ＆ コイン +3");}else{chinLevel=Math.max(-4,chinLevel-2);showToast("ハズレ！ アゴが縮んだ…");}powered=chinLevel>0;ui();}}
 for(const e of enemies){if(!e.alive)continue;e.x+=e.v;if(e.x<e.min||e.x>e.max)e.v*=-1;const er={x:e.x,y:e.y,w:38,h:32},hr={x:hero.x+7,y:hero.y+8,w:hero.w-14,h:hero.h-8};
 if(hit(hr,er)){const inFront=(e.x+19-hero.x-hero.w/2)*hero.face>0;if(chinLevel>=2&&inFront){e.alive=false;coins+=3;ui();}else if(hero.vy>1&&oldY+hero.h<e.y+13){e.alive=false;hero.vy=-9;coins+=2;ui();}else damage();}}
 // 大型ボス：予備動作→突進→隙のサイクル。アゴが2以上なら正面から反撃できる。
 if(stageNo===3&&boss.alive){
   if(hero.x>3150)document.getElementById("bossStat").style.display="inline-block";
   if(boss.hitCooldown>0)boss.hitCooldown--;
   if(boss.flash>0)boss.flash--;
   const heroCenter=hero.x+hero.w/2, bossCenter=boss.x+boss.w/2, dx=heroCenter-bossCenter;
   if(boss.mode==="wait"){boss.modeTimer++;if(Math.abs(dx)<520&&boss.modeTimer>70){boss.mode="tell";boss.modeTimer=0;}}
   else if(boss.mode==="tell"){boss.modeTimer++;if(boss.modeTimer>45){boss.mode="charge";boss.modeTimer=0;boss.chargeDir=dx<0?-1:1;}}
   else if(boss.mode==="charge"){boss.x+=boss.chargeDir*6.2;boss.modeTimer++;if(boss.modeTimer>32){boss.mode="recover";boss.modeTimer=0;}}
   else if(boss.mode==="recover"){boss.modeTimer++;if(boss.modeTimer>65){boss.mode="wait";boss.modeTimer=0;}}
   boss.x=Math.max(3300,Math.min(3980,boss.x));
   const br={x:boss.x+18,y:boss.y+15,w:boss.w-36,h:boss.h-15}, hr={x:hero.x+7,y:hero.y+8,w:hero.w-14,h:hero.h-8};
   if(hit(hr,br)){
     const inFront=(bossCenter-heroCenter)*hero.face>0;
     if(chinLevel>=2&&inFront&&boss.mode==="recover"&&boss.hitCooldown===0){
       boss.hp--;boss.hitCooldown=45;boss.flash=12;coins+=5;showToast("ボスにアゴ攻撃！ +5コイン");ui();
       if(boss.hp<=0){boss.alive=false;bossDefeated=true;bossDefeatTimeLeft=Math.max(0,timeLeft);coins+=20;const timeBonus=Math.floor(bossDefeatTimeLeft)*10;showToast("象の老武術家を撃破！ +20コイン ＆ タイムボーナス +"+timeBonus+"pt");ui();}
     }else if(boss.mode==="charge"&&hero.inv===0)damage();
   }
 }
 if(hero.inv>0)hero.inv--;if(frame%4===0)ui();camera=Math.max(0,Math.min(worldW-W,hero.x-W*.36));if(hero.x>stage.end-145){if(stageNo!==3)finishGate();else if(bossDefeated)finishGate();}}
function background(){
 // Cinematic layered fantasy valley: sky, distant citadels, cliffs, river and foreground grass.
 const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1674c8');sky.addColorStop(.42,'#72d8ff');sky.addColorStop(1,'#ffe2a4');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // sun glow
 const sun=ctx.createRadialGradient(760,92,4,760,92,210);sun.addColorStop(0,'#fffde4aa');sun.addColorStop(1,'#fffde400');ctx.fillStyle=sun;ctx.fillRect(520,-100,480,400);
 // cloud banks
 for(let i=0;i<10;i++){let x=((i*151-camera*.13)%(W+260)+W+260)%(W+260)-120,y=55+(i%4)*35;ctx.fillStyle=i%2?'#ffffffb8':'#f3fbff9c';ctx.beginPath();ctx.ellipse(x,y,48,17,0,0,Math.PI*2);ctx.ellipse(x+30,y-10,34,23,0,0,Math.PI*2);ctx.ellipse(x+61,y,45,16,0,0,Math.PI*2);ctx.fill();}
 // distant mountain/cliff silhouettes
 for(let layer=0;layer<3;layer++){let base=365+layer*35;ctx.fillStyle=['#7baec4','#4e879b','#356d79'][layer];ctx.beginPath();ctx.moveTo(0,H);for(let x=-100;x<=W+100;x+=55){let xx=x-camera*(.08+layer*.08);let yy=base-38*Math.sin((x+layer*77)*.012)-23*Math.sin(x*.031+layer);ctx.lineTo(xx,yy);}ctx.lineTo(W,H);ctx.closePath();ctx.fill();}
 // castle towers repeated in the far distance
 for(let i=0;i<8;i++){let x=((i*185-camera*.20)%(W+220)+W+220)%(W+220)-80;let base=350+(i%3)*18;let scale=.62+(i%4)*.12;ctx.save();ctx.translate(x,base);ctx.scale(scale,scale);ctx.fillStyle='#e6e4d7';ctx.strokeStyle='#8babc0';ctx.lineWidth=2;ctx.fillRect(-26,-76,52,76);ctx.fillRect(-39,-54,18,54);ctx.fillRect(21,-64,18,64);ctx.beginPath();ctx.moveTo(-31,-76);ctx.lineTo(0,-124);ctx.lineTo(31,-76);ctx.closePath();ctx.fillStyle='#536d92';ctx.fill();ctx.beginPath();ctx.moveTo(-43,-54);ctx.lineTo(-30,-81);ctx.lineTo(-17,-54);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(17,-64);ctx.lineTo(30,-91);ctx.lineTo(43,-64);ctx.closePath();ctx.fill();ctx.fillStyle='#f8d58a';for(let wy=-61;wy<-15;wy+=23){ctx.fillRect(-15,wy,7,11);ctx.fillRect(8,wy,7,11);}ctx.restore();}
 // river glint
 const water=ctx.createLinearGradient(0,365,0,470);water.addColorStop(0,'#4ac9ed');water.addColorStop(1,'#197db0');ctx.fillStyle=water;ctx.fillRect(0,370,W,100);ctx.strokeStyle='#d7fbff88';ctx.lineWidth=2;for(let i=0;i<22;i++){let x=((i*73-camera*.27)%(W+80)+W+80)%(W+80)-30,y=384+(i%6)*13;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+24+(i%4)*9,y);ctx.stroke();}
 // sunlit grassy bank and foreground texture
 const land=ctx.createLinearGradient(0,425,0,H);land.addColorStop(0,'#b8d96b');land.addColorStop(.2,'#689e48');land.addColorStop(1,'#34583b');ctx.fillStyle=land;ctx.beginPath();ctx.moveTo(0,432);for(let x=0;x<=W+20;x+=25)ctx.lineTo(x,428+Math.sin((x+camera*.2)*.04)*5+Math.sin(x*.013)*4);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fill();
 for(let i=0;i<110;i++){let x=((i*47-camera*.6)%(W+30)+W+30)%(W+30)-10,y=438+(i*31%104);ctx.strokeStyle=['#e4d989','#90c65c','#376f43','#f9d78a'][i%4];ctx.lineWidth=i%5===0?2:1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-2+(i%5),y-4-(i%7));ctx.stroke();}
}
function drawPlatform(p){
 const soil=ctx.createLinearGradient(0,p.y,0,p.y+p.h);soil.addColorStop(0,'#8a6a48');soil.addColorStop(.16,'#69452f');soil.addColorStop(1,'#392d2b');ctx.fillStyle=soil;ctx.fillRect(p.x,p.y,p.w,p.h);
 ctx.fillStyle='#79c94d';ctx.fillRect(p.x,p.y,p.w,9);ctx.fillStyle='#c4e878';ctx.fillRect(p.x,p.y,p.w,2);
 for(let x=p.x+5;x<p.x+p.w;x+=13){ctx.strokeStyle=(Math.floor(x/13)%2)?'#4f9c43':'#a4d65a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,p.y+2);ctx.lineTo(x-2,p.y-3-(x%4));ctx.stroke();}
 for(let x=p.x+18;x<p.x+p.w;x+=39){ctx.strokeStyle='#a17a53';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x,p.y+18);ctx.lineTo(x+4,p.y+Math.min(p.h,38));ctx.lineTo(x+11,p.y+Math.min(p.h,42));ctx.stroke();ctx.fillStyle='#b9976d';ctx.fillRect(x+18,p.y+27,3,2);}
}
function drawHero(){
 if(hero.inv&&Math.floor(frame/5)%2===0)return;
 let pose='idle';
 if(!hero.ground) pose=hero.vy<0?'jump':'crouch';
 else if(Math.abs(hero.vx)>0) pose=Math.floor(frame/7)%2?'run1':'run2';
 else if(keys.down) pose='crouch';
 const spr=sprites[pose]||sprites.idle;
 if(!spr||!spr.complete||!spr.naturalWidth)return;
 // Use clean, individually cropped frames from the original character design sheet.
 const drawH=hero.ground?94:100, drawW=drawH*spr.naturalWidth/spr.naturalHeight;
 const dx=hero.x+(hero.w-drawW)/2, dy=hero.y+hero.h-drawH+8;
 ctx.save();
 if(hero.face<0){ctx.translate(hero.x+hero.w,0);ctx.scale(-1,1);ctx.translate(-hero.x,0);}
 ctx.drawImage(spr,dx,dy,drawW,drawH);
 if(chinLevel!==0){const amount=chinLevel>0?chinLevel*22:chinLevel*8;const ax=hero.x+hero.w*0.60,ay=hero.y+hero.h*0.49;ctx.fillStyle=chinLevel>0?'#f0b28b':'#c88968';ctx.strokeStyle='#874b34';ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(ax-7,ay-5);ctx.quadraticCurveTo(ax+4,ay+1,ax+10,ay+7);ctx.lineTo(ax+Math.max(3,amount+10),ay+16);ctx.quadraticCurveTo(ax+Math.max(10,amount+20),ay+26,ax+Math.max(2,amount+12),ay+31);ctx.quadraticCurveTo(ax+Math.max(-4,amount),ay+36,ax+4,ay+25);ctx.lineTo(ax-5,ay+10);ctx.quadraticCurveTo(ax-10,ay+1,ax-7,ay-5);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=chinLevel>0?'#fff09a':'#dbe5f2';ctx.font='bold 13px system-ui';ctx.fillText(chinLevel>0?`アゴ +${chinLevel}`:`アゴ ${chinLevel}`,hero.x-8,hero.y-10);}ctx.restore();
}
function coin(q){if(q.got)return;let y=q.y+Math.sin(frame*.09+q.x)*3;ctx.fillStyle='#f7a928';ctx.beginPath();ctx.ellipse(q.x,y,10,13,0,0,7);ctx.fill();ctx.strokeStyle='#fff078';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#fff3b0';ctx.fillRect(q.x-2,y-7,4,14);}
function mushroom(m){if(m.got)return;let x=m.x,y=m.y+Math.sin(frame*.08+m.x)*3;const cap=m.lucky?'#ef3348':'#2688ff',glow=m.lucky?'#ff5264':'#55a5ff';ctx.save();ctx.shadowColor=glow;ctx.shadowBlur=12+Math.sin(frame*.3+m.x)*5;ctx.fillStyle='#f3dfb7';ctx.fillRect(x-10,y-2,20,17);ctx.fillStyle=cap;ctx.beginPath();ctx.arc(x,y-4,17,Math.PI,0);ctx.lineTo(x+17,y-4);ctx.lineTo(x-17,y-4);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff8df';for(const [dx,dy,r] of [[-8,-10,4],[5,-13,5],[10,-3,3]]){ctx.beginPath();ctx.arc(x+dx,y+dy,r,0,7);ctx.fill();}ctx.fillStyle='#26354a';ctx.fillRect(x-7,y+4,4,5);ctx.fillRect(x+3,y+4,4,5);ctx.fillStyle='#fff';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.fillText(m.lucky?'当たり':'ハズレ',x,y+30);ctx.textAlign='left';ctx.restore();}
function enemy(e){if(!e.alive)return;ctx.save();ctx.translate(e.x,e.y);ctx.shadowColor='#1d1530';ctx.shadowBlur=8;let bob=Math.sin(frame*.12+e.x)*2;ctx.fillStyle='#7b3fb0';ctx.beginPath();ctx.ellipse(20,17+bob,21,17,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#b98be5';ctx.beginPath();ctx.ellipse(15,10+bob,9,6,-.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(12,14+bob,5,7,0,0,Math.PI*2);ctx.ellipse(27,14+bob,5,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#20162b';ctx.beginPath();ctx.arc(13,15+bob,2.3,0,Math.PI*2);ctx.arc(28,15+bob,2.3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f2d4ff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(5,27+bob);ctx.lineTo(1,33+bob);ctx.moveTo(31,27+bob);ctx.lineTo(36,32+bob);ctx.stroke();ctx.restore();}
function drawBoss(){
 if(!boss.alive)return;
 const x=boss.x,y=boss.y;ctx.save();
 const pose=boss.mode==="charge"?3:(boss.mode==="tell"?2:(Math.floor(frame/18)%2===0?0:1));
 const spr=bossSprites[pose];
 // Use the hand-painted elephant martial-artist sprite frames, not geometric placeholder art.
 const dh=205,dw=(spr&&spr.naturalHeight)?dh*spr.naturalWidth/spr.naturalHeight:190,dx=x+(boss.w-dw)/2,dy=y+boss.h-dh;
 if(spr&&spr.complete&&spr.naturalWidth){
   if(boss.flash>0){ctx.globalAlpha=0.55+Math.sin(frame)*0.25;ctx.filter='brightness(1.7) saturate(1.3)';}
   const lean=boss.mode==="charge"?-0.055:(boss.mode==="tell"?0.025:Math.sin(frame/16)*0.012);
   ctx.translate(dx+dw/2,dy+dh);ctx.rotate(lean);ctx.drawImage(spr,-dw/2,-dh,dw,dh);
   ctx.filter='none';ctx.globalAlpha=1;
 }else{
   ctx.fillStyle="#242d3a";ctx.fillRect(x+30,y+35,80,90);
 }
 if(boss.mode==="tell"){
   ctx.fillStyle="#ffdc54";ctx.font="bold 28px system-ui";ctx.textAlign="center";ctx.shadowColor="#ff6b22";ctx.shadowBlur=15;ctx.fillText("!!",x+82,y-22);ctx.shadowBlur=0;
 }
 if(boss.mode==="charge"){
   ctx.strokeStyle="#ffb347";ctx.lineWidth=7;ctx.lineCap="round";ctx.shadowColor="#ff6b22";ctx.shadowBlur=18;
   ctx.beginPath();ctx.moveTo(x+10,y+65);ctx.quadraticCurveTo(x-45,y+42,x-75,y+72);ctx.moveTo(x+12,y+88);ctx.quadraticCurveTo(x-42,y+75,x-68,y+102);ctx.stroke();ctx.shadowBlur=0;
 }
 ctx.restore();
}
function draw(){background();ctx.save();ctx.translate(-camera,0);platforms.forEach(drawPlatform);coinList.forEach(coin);mushrooms.forEach(mushroom);enemies.forEach(enemy);if(stageNo===3)drawBoss();ctx.fillStyle='#fff';ctx.fillRect(stage.end-110,285,7,177);ctx.fillStyle='#ff4b56';ctx.beginPath();ctx.moveTo(stage.end-103,290);ctx.lineTo(stage.end-48,310);ctx.lineTo(stage.end-103,330);ctx.fill();drawHero();ctx.restore();ctx.fillStyle='#18304c';ctx.font='bold 17px system-ui';ctx.save();ctx.fillStyle='#07172caa';ctx.beginPath();ctx.roundRect(12,10,Math.min(640,W-24),34,10);ctx.fill();ctx.strokeStyle='#9ddcff88';ctx.lineWidth=1.5;ctx.stroke();ctx.fillStyle='#fff';ctx.shadowColor='#06162c';ctx.shadowBlur=4;ctx.font='bold 17px system-ui';ctx.fillText(stageNo===3?(bossDefeated?'ボス撃破！ゴールへ進め！':'突進後の隙にアゴ攻撃！'):(stageNo===1?'コイン収集！350点以上でSTAGE 2へ':'累計750点以上でボスに挑戦！'),22,33);ctx.restore();if(toastUntil>frame){ctx.fillStyle='#172b49';ctx.beginPath();ctx.roundRect(270,52,420,50,12);ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 19px system-ui';ctx.textAlign='center';ctx.fillText(toastText,480,83);ctx.textAlign='left';}}
function loop(){if(sheet.complete&&sheet.naturalWidth&&!Object.keys(sprites).length)makeSprites();update();draw();requestAnimationFrame(loop)}
reset();title();loop();
